script:
(function () {
  'use strict';
  // ===== Tax figures: tax year 2026 =====
  // Ordinary brackets and capital gains breakpoints: IRS Rev. Proc. 2025-32, sections 4.01 and 4.03
  // (2026 inflation adjustments, as amended by the One, Big, Beautiful Bill Act).
  // Capital loss deduction limit: IRC section 1211(b), $3,000 ($1,500 married filing separately), not indexed.
  // Net investment income tax: IRC section 1411, 3.8%; thresholds are not indexed.
  // Wash sale window: IRC section 1091, 30 days before or after the sale.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj: [24800, 100800, 211400, 403550, 512450, 768700],
    hoh: [17700, 67450, 105700, 201750, 256200, 640600],
    mfs: [12400, 50400, 105700, 201775, 256225, 384350]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { // taxable income where the 0% rate ends and the 15% rate ends
    single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850]
  };
  var LOSS_LIMIT = { single: 3000, mfj: 3000, hoh: 3000, mfs: 1500 };
  var NIIT_RATE = 0.038;
  // ======================================
  // Method: federal tax is worked out twice, without and with the harvested loss, using the
  // Schedule D netting rules (short-term and long-term netted separately, then against each other;
  // a net loss is deductible up to the limit and the rest carries forward, short-term used first)
  // and the qualified dividends and capital gain tax worksheet stacking (preferential gains on top).
  // Verified: single, $90,000 ordinary taxable income, $2,000 short-term and $3,000 long-term gains,
  // $8,000 short-term loss -> tax $15,402 before, $13,852 after, saving $1,550
  // (= $2,000 x 22% + $3,000 x 15% + $3,000 x 22%), nothing carried forward; 5% state -> $400.
  // Rate-table checks: single $92,000 ordinary = $14,952; MFJ $211,400 = $35,932 (Rev. Proc. table).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function optNum(id) { var v = num(id); return isNaN(v) ? 0 : v; }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  function federal(status, ordinary, st, lt) {
    var net = st + lt, pref = 0, ordGain = 0, deduction = 0, used = 0, carrySt = 0, carryLt = 0;
    if (net >= 0) {
      pref = lt > 0 ? Math.min(lt, net) : 0;
      ordGain = net - pref;
    } else {
      deduction = Math.min(-net, LOSS_LIMIT[status]);
      used = Math.min(deduction, Math.max(0, ordinary));
      if (st < 0 && lt < 0) {
        carrySt = Math.max(0, -st - used);
        carryLt = -lt - Math.max(0, used - (-st));
      } else if (st < 0) {
        carrySt = -net - used;
      } else {
        carryLt = -net - used;
      }
    }
    var taxable = Math.max(0, ordinary + ordGain + pref - deduction);
    var gains = Math.min(pref, taxable), base = taxable - gains;
    var b = CG_BREAKS[status];
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    var tax = Math.min(ordinaryTax(base, status) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, status));
    return { st: st, lt: lt, included: Math.max(0, net), used: used, taxable: taxable, tax: tax,
             carrySt: carrySt, carryLt: carryLt, carry: carrySt + carryLt };
  }

  function harvest(p) {
    var st = p.stGains - p.stCarry, lt = p.ltGains - p.ltCarry;
    var before = federal(p.status, p.ordinary, st, lt);
    var after = p.longTerm ? federal(p.status, p.ordinary, st, lt - p.loss) : federal(p.status, p.ordinary, st - p.loss, lt);
    var fed = before.tax - after.tax;
    var state = p.stateRate * (before.taxable - after.taxable);
    var niit = p.niit ? NIIT_RATE * (before.included - after.included) : 0;
    var net = fed + state + niit - p.costs;
    return {
      before: before, after: after, fed: fed, state: state, niit: niit, net: net,
      offsetGains: before.included - after.included, offsetIncome: after.used - before.used,
      carried: after.carry - before.carry
    };
  }

  function parseDate(v) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v || '');
    if (!m) return null;
    var d = new Date(+m[1], +m[2] - 1, +m[3]);
    return isNaN(d.getTime()) ? null : d;
  }
  function addDays(d, n) { return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n); }
  function longDate(d) { return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }); }

  function fill(rows) {
    var body = document.getElementById('thTable');
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function update() {
    var status = document.getElementById('thStatus').value;
    var ordinary = num('thIncome'), stGains = num('thStGains'), ltGains = num('thLtGains'),
        basis = num('thBasis'), value = num('thValue');
    var stCarry = optNum('thStCarry'), ltCarry = optNum('thLtCarry'), stateRate = optNum('thState'), costs = optNum('thCosts');
    var error = document.getElementById('thError');
    var msg = '';
    if ([ordinary, stGains, ltGains, basis, value].some(isNaN)) msg = 'Fill in your income, gains, cost basis and current value.';
    else if (ordinary < 0 || basis < 0 || value < 0) msg = 'Income, cost basis and current value cannot be negative.';
    else if (stCarry < 0 || ltCarry < 0 || costs < 0) msg = 'Enter carryovers and trading costs as positive amounts.';
    else if (stateRate < 0 || stateRate > 20) msg = 'Use a state tax rate from 0% to 20%.';
    else if (value >= basis) msg = 'This position is worth at least what you paid, so there is no loss to harvest.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var p = { status: status, ordinary: ordinary, stGains: stGains, ltGains: ltGains, stCarry: stCarry, ltCarry: ltCarry,
              loss: basis - value, longTerm: document.getElementById('thHolding').value === 'long',
              stateRate: stateRate / 100, niit: document.getElementById('thNiit').checked, costs: costs };
    var r = harvest(p);
    set('thNet', money.format(r.net));
    set('thLoss', money.format(p.loss) + (p.longTerm ? ' long-term' : ' short-term'));
    set('thRate', p.loss > 0 ? (r.net / p.loss * 100).toFixed(1) + '%' : '–');
    set('thFed', money.format(r.fed));
    set('thStateSave', money.format(r.state));
    set('thNiitSave', money.format(r.niit));
    set('thCostsShow', costs > 0 ? '−' + money.format(costs) : money.format(0));
    set('thOffGains', money.format(r.offsetGains));
    set('thOffIncome', money.format(r.offsetIncome));
    set('thCarried', money.format(r.carried));

    var b = r.before, a = r.after, next = String(TAX_YEAR + 1);
    fill([
      ['Net short-term gain (loss)', signed(b.st), signed(a.st)],
      ['Net long-term gain (loss)', signed(b.lt), signed(a.lt)],
      ['Capital loss deducted from income', money.format(b.used), money.format(a.used)],
      ['Federal taxable income', money.format(b.taxable), money.format(a.taxable)],
      ['Federal income tax', money.format(b.tax), money.format(a.tax)],
      ['Short-term loss carried to ' + next, money.format(b.carrySt), money.format(a.carrySt)],
      ['Long-term loss carried to ' + next, money.format(b.carryLt), money.format(a.carryLt)]
    ]);

    var dateEl = document.getElementById('thSaleDate');
    var sale = parseDate(dateEl.value);
    if (sale) {
      set('thWashStart', longDate(addDays(sale, -30)));
      set('thWashEnd', longDate(addDays(sale, 30)));
      set('thRebuy', longDate(addDays(sale, 31)));
    } else {
      set('thWashStart', '–'); set('thWashEnd', '–'); set('thRebuy', 'Enter a sale date');
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('thForm');
    if (!form) return;
    var dateEl = document.getElementById('thSaleDate');
    if (!dateEl.value) {
      var t = new Date();
      dateEl.value = t.getFullYear() + '-' + ('0' + (t.getMonth() + 1)).slice(-2) + '-' + ('0' + t.getDate()).slice(-2);
    }
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
